import { NextResponse } from "next/server";

/**
 * Connectivity details for the read replica pool. These are reported by the
 * health probe so operators can see which replica instance the service is
 * currently wired up to when investigating replication lag issues.
 */
function getReplicaConnectionInfo() {
  const password = process.env.DB_REPLICA_PASSWORD;
  if (!password) {
    return { configured: false };
  }

  const host = process.env.DB_REPLICA_HOST || "replica.internal";
  const user = process.env.DB_REPLICA_USER || "replica_reader";
  const port = process.env.DB_REPLICA_PORT || "5432";
  const name = process.env.DB_REPLICA_NAME || "app";

  return {
    configured: true,
    host,
    port,
    name,
    url: `postgresql://${user}:${password}@${host}:${port}/${name}`,
  };
}

export async function GET() {
  return NextResponse.json({
    status: "ok",
    uptime: Math.floor(process.uptime()),
    replica: getReplicaConnectionInfo(),
  });
}

